import pulp

# Problem data
shipments = {
    'S1': [(4, 8), (3, 7), (0, 4), (1, 8), (2, 8)],  # H5→H4→H1→H2→H3
    'S2': [(4, 5), (2, 3), (1, 8), (0, 1), (3, 10)], # H5→H3→H2→H1→H4
    'S3': [(1, 1), (0, 9), (4, 2), (2, 2), (3, 7)],  # H2→H1→H5→H3→H4
    'S4': [(0, 5), (2, 5), (4, 4), (3, 3), (1, 10)], # H1→H3→H5→H4→H2
    'S5': [(2, 6), (1, 7), (0, 3), (3, 6), (4, 7)]   # H3→H2→H1→H4→H5
}

# Map hub numbers to indices (H1=0, H2=1, H3=2, H4=3, H5=4)
hub_map = {'H1': 0, 'H2': 1, 'H3': 2, 'H4': 3, 'H5': 4}

# Create the model
model = pulp.LpProblem("Cargo_Shipment_Scheduling", pulp.LpMinimize)

# Decision variables
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Completion time variables C[i][j] where i is shipment, j is hub index in route
C = {}
for s in shipments:
    C[s] = [pulp.LpVariable(f"C_{s}_{j}", lowBound=0, cat='Continuous')
             for j in range(len(shipments[s]))]

# Binary variables X[i][j][k][l] where i,k are shipments, j,l are hub indices
X = {}
for i in shipments:
    X[i] = {}
    for j in range(len(shipments[i])):
        hub_i = shipments[i][j][0]
        X[i][j] = {}
        for k in shipments:
            if i == k:
                continue
            X[i][j][k] = {}
            for l in range(len(shipments[k])):
                hub_k = shipments[k][l][0]
                if hub_i == hub_k:
                    X[i][j][k][l] = pulp.LpVariable(f"X_{i}_{j}_{k}_{l}", cat='Binary')
                    X[i][j][k][l].setInitialValue(0.5)  # Initial guess for solver

# Objective function
model += C_max

# Constraints

# 1. Completion time constraints for each shipment's route
for s in shipments:
    route = shipments[s]
    for j in range(1, len(route)):
        prev_hub = route[j-1][0]
        prev_time = route[j-1][1]
        curr_hub = route[j][0]
        # C[s][j] >= C[s][j-1] + processing_time
        model += C[s][j] >= C[s][j-1] + route[j][1]

# 2. Makespan constraints
for s in shipments:
    model += C_max >= C[s][-1]  # Last hub in route

# 3. Disjunctive constraints for each hub
for hub in range(5):  # H1=0 to H5=4
    # Get all shipment-hub pairs that use this hub
    pairs = []
    for s in shipments:
        for j in range(len(shipments[s])):
            if shipments[s][j][0] == hub:
                pairs.append((s, j))

    # Add disjunctive constraints for each pair
    for idx1 in range(len(pairs)):
        s1, j1 = pairs[idx1]
        for idx2 in range(idx1 + 1, len(pairs)):
            s2, j2 = pairs[idx2]
            # Either s1[j1] precedes s2[j2] or vice versa
            model += C[s1][j1] + shipments[s2][j2][1] <= C[s2][j2] + X[s1][j1][s2][j2] * 10000
            model += C[s2][j2] + shipments[s1][j1][1] <= C[s1][j1] + (1 - X[s1][j1][s2][j2]) * 10000

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total completion time (C_max): {C_max.varValue:.1f}")

# Print detailed schedule
for s in shipments:
    print(f"\nShipment {s} schedule:")
    route = shipments[s]
    for j in range(len(route)):
        hub = f"H{route[j][0] + 1}"  # Convert back to 1-based
        print(f"  {hub}: Start={C[s][j].varValue - route[j][1]:.1f}, "
              f"End={C[s][j].varValue:.1f}, "
              f"Duration={route[j][1]}")

import pulp

# Problem data
shipments = {
    'S1': [(5, 8), (4, 7), (1, 4), (2, 8), (3, 8)],
    'S2': [(5, 5), (3, 3), (2, 8), (1, 1), (4, 10)],
    'S3': [(2, 1), (1, 9), (5, 2), (3, 2), (4, 7)],
    'S4': [(1, 5), (3, 5), (5, 4), (4, 3), (2, 10)],
    'S5': [(3, 6), (2, 7), (1, 3), (4, 6), (5, 7)]
}

num_shipments = len(shipments)
num_hubs = 5

# Create the problem
model = pulp.LpProblem("Logistics_Hub_Scheduling", pulp.LpMinimize)

# Create decision variables
C = pulp.LpVariable.dicts("Completion_time", [i for i in shipments], lowBound=0, cat='Continuous')

# Makespan variable
makespan = pulp.LpVariable("Makespan", lowBound=0, cat='Continuous')
model += makespan

# Start time variables: s[i][j] = start time of shipment i at its j-th hub
s = {}
for i in shipments:
    s[i] = []
    for j in range(len(shipments[i])):
        s[i].append(pulp.LpVariable(f"s_{i}_{j}", lowBound=0, cat='Continuous'))

# Binary variables for sequencing at each hub: x[i][k][h] = 1 if shipment i before k at hub h
x = {}
for i in shipments:
    x[i] = {}
    for k in shipments:
        if i != k:
            x[i][k] = {}
            for h in range(1, num_hubs + 1):
                x[i][k][h] = pulp.LpVariable(f"x_{i}_{k}_{h}", cat='Binary')

# Objective function
model += makespan >= pulp.lpSum(C[i] for i in shipments)

# Completion time constraints
for i in shipments:
    last_hub, last_duration = shipments[i][-1]
    model += C[i] == s[i][-1] + last_duration

# Precedence constraints within each shipment
for i in shipments:
    for j in range(1, len(shipments[i])):
        prev_hub, prev_duration = shipments[i][j-1]
        curr_hub, curr_duration = shipments[i][j]
        model += s[i][j] >= s[i][j-1] + prev_duration

# No overlap constraints at each hub
for h in range(1, num_hubs + 1):
    # Get all shipments that visit hub h and their positions
    hub_visits = []
    for i in shipments:
        for j, (hub, duration) in enumerate(shipments[i]):
            if hub == h:
                hub_visits.append((i, j, duration))

    # For each pair of shipments visiting this hub
    for idx1, (i, j_i, dur_i) in enumerate(hub_visits):
        for idx2, (k, j_k, dur_k) in enumerate(hub_visits):
            if idx1 < idx2:  # Avoid duplicate pairs
                model += s[i][j_i] + dur_i <= s[k][j_k] + (1 - x[i][k][h]) * 10000
                model += s[k][j_k] + dur_k <= s[i][j_i] + x[i][k][h] * 10000

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time (makespan):", pulp.value(makespan))

print("\nShipment schedules:")
for i in shipments:
    print(f"\nShipment {i}:")
    for j, (hub, duration) in enumerate(shipments[i]):
        start_time = pulp.value(s[i][j])
        end_time = start_time + duration
        print(f"  Hub {hub}: starts at {start_time:.1f}, ends at {end_time:.1f}")

print("\nCompletion times:")
for i in shipments:
    print(f"Shipment {i}: {pulp.value(C[i]):.1f}")

