# Decision variables
# Start time of each operation
start_times = {}
for shipment in shipments:
    for step, (hub, duration) in enumerate(shipments[shipment]):
        start_times[(shipment, step)] = pulp.LpVariable(
            f"start_{shipment}_step{step}", lowBound=0, cat='Continuous')

# Completion time variables
completion_times = {}
for shipment in shipments:
    last_step = len(shipments[shipment]) - 1
    hub, duration = shipments[shipment][last_step]
    completion_times[shipment] = start_times[(shipment, last_step)] + duration

# Makespan variable
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for sequencing at each hub
hubs = ['H1', 'H2', 'H3']
sequence_vars = {}
M = 1000  # Big M constant

for hub in hubs:
    # Find all operations at this hub
    operations = []
    for shipment in shipments:
        for step, (h, duration) in enumerate(shipments[shipment]):
            if h == hub:
                operations.append((shipment, step, duration))

    # Create binary variables for each pair of operations at this hub
    for i, (ship_i, step_i, dur_i) in enumerate(operations):
        for j, (ship_j, step_j, dur_j) in enumerate(operations):
            if i < j:  # Avoid duplicate pairs
                var_name = f"seq_{hub}_{ship_i}_s{step_i}_{ship_j}_s{step_j}"
                sequence_vars[(hub, ship_i, step_i, ship_j, step_j)] = pulp.LpVariable(
                    var_name, cat='Binary')
                # Create the complementary variable
                var_name_rev = f"seq_{hub}_{ship_j}_s{step_j}_{ship_i}_s{step_i}"
                sequence_vars[(hub, ship_j, step_j, ship_i, step_i)] = 1 - sequence_vars[(hub, ship_i, step_i, ship_j, step_j)]

# Objective function
model += makespan

# Constraints
# 1. Makespan definition
for shipment in shipments:
    model += makespan >= completion_times[shipment]

# 2. Precedence constraints within each shipment
for shipment in shipments:
    for step in range(len(shipments[shipment]) - 1):
        current_hub, current_dur = shipments[shipment][step]
        next_hub, next_dur = shipments[shipment][step + 1]
        model += start_times[(shipment, step + 1)] >= start_times[(shipment, step)] + current_dur

# 3. Hub capacity constraints
for hub in hubs:
    operations = []
    for shipment in shipments:
        for step, (h, duration) in enumerate(shipments[shipment]):
            if h == hub:
                operations.append((shipment, step, duration))

    for i, (ship_i, step_i, dur_i) in enumerate(operations):
        for j, (ship_j, step_j, dur_j) in enumerate(operations):
            if i < j:  # Only create constraints for unique pairs
                # Either ship_i precedes ship_j or vice versa
                model += start_times[(ship_i, step_i)] >= start_times[(ship_j, step_j)] + dur_j - \
                         M * sequence_vars[(hub, ship_i, step_i, ship_j, step_j)]
                model += start_times[(ship_j, step_j)] >= start_times[(ship_i, step_i)] + dur_i - \
                         M * sequence_vars[(hub, ship_j, step_j, ship_i, step_i)]

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time (makespan):", pulp.value(makespan))

for shipment in shipments:
    print(f"\nShipment {shipment}:")
    for step, (hub, duration) in enumerate(shipments[shipment]):
        start = pulp.value(start_times[(shipment, step)])
        end = start + duration
