import pulp

# Initialize the problem
model = pulp.LpProblem("Cargo_Shipment_Scheduling", pulp.LpMinimize)

# Problem data
shipments = ['S1', 'S2', 'S3']
hubs = ['H1', 'H2', 'H3']
routes = {
    'S1': [('H2', 2), ('H1', 2), ('H3', 6)],
    'S2': [('H2', 7), ('H1', 6), ('H3', 10)],
    'S3': [('H3', 8), ('H1', 9), ('H2', 5)]
}

# Decision variables
# Completion time of each shipment
C = pulp.LpVariable.dicts("Completion", shipments, lowBound=0, cat='Continuous')

# Start time of each operation (shipment, hub, position in route)
start = {}
for s in shipments:
    for pos, (h, dur) in enumerate(routes[s]):
        start[(s, h, pos)] = pulp.LpVariable(f"start_{s}_{h}_{pos}", lowBound=0, cat='Continuous')

# Binary variables for sequencing at each hub
# y[(s1, s2, h, p1, p2)] = 1 if s1 comes before s2 at hub h (positions p1, p2)
y = {}
for h in hubs:
    for s1 in shipments:
        for s2 in shipments:
            if s1 != s2:
                # Find positions where both shipments visit hub h
                positions_s1 = [(pos, dur) for pos, (hub, dur) in enumerate(routes[s1]) if hub == h]
                positions_s2 = [(pos, dur) for pos, (hub, dur) in enumerate(routes[s2]) if hub == h]

                for (p1, dur1) in positions_s1:
                    for (p2, dur2) in positions_s2:
                        y[(s1, s2, h, p1, p2)] = pulp.LpVariable(
                            f"y_{s1}_{s2}_{h}_{p1}_{p2}", cat='Binary')

# Objective: minimize the makespan (maximum completion time)
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')
model += makespan
for s in shipments:
    model += makespan >= C[s]

# Constraints

# 1. Precedence constraints within each shipment's route
for s in shipments:
    for pos in range(len(routes[s]) - 1):
        h_current, dur_current = routes[s][pos]
        h_next, dur_next = routes[s][pos + 1]
        model += start[(s, h_next, pos + 1)] >= start[(s, h_current, pos)] + dur_current

# 2. Completion time definition
for s in shipments:
    last_h, last_dur = routes[s][-1]
    last_pos = len(routes[s]) - 1
    model += C[s] == start[(s, last_h, last_pos)] + last_dur

# 3. No-overlap constraints at each hub
for h in hubs:
    for s1 in shipments:
        for s2 in shipments:
            if s1 != s2:
                # Find positions where both shipments visit hub h
                positions_s1 = [(pos, dur) for pos, (hub, dur) in enumerate(routes[s1]) if hub == h]
                positions_s2 = [(pos, dur) for pos, (hub, dur) in enumerate(routes[s2]) if hub == h]

                for (p1, dur1) in positions_s1:
                    for (p2, dur2) in positions_s2:
                        # Either s1 comes before s2 or vice versa
                        model += start[(s1, h, p1)] + dur1 <= start[(s2, h, p2)] + y[(s1, s2, h, p1, p2)] * 1e6
                        model += start[(s2, h, p2)] + dur2 <= start[(s1, h, p1)] + (1 - y[(s1, s2, h, p1, p2)]) * 1e6

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time (makespan):", pulp.value(makespan))
print("\nShipment completion times:")
for s in shipments:
    print(f"{s}: {pulp.value(C[s])}")

print("\nOperation start times:")
for s in shipments:
    for pos, (h, dur) in enumerate(routes[s]):
        print(f"{s} at {h} (position {pos}): {pulp.value(start[(s, h, pos)])}")

import pulp

# Initialize the model
model = pulp.LpProblem("Cargo_Shipment_Scheduling", pulp.LpMinimize)

# Problem data
shipments = {
    'S1': [(1, 2), (0, 2), (2, 6)],  # (hub_index, duration)
    'S2': [(1, 7), (0, 6), (2, 10)],
    'S3': [(2, 8), (0, 9), (1, 5)]
}

num_shipments = len(shipments)
num_hubs = 3
hub_names = ['H1', 'H2', 'H3']

# Create decision variables
start_vars = {}
for s_name, route in shipments.items():
    for step, (hub_idx, dur) in enumerate(route):
        start_vars[(s_name, step)] = pulp.LpVariable(f"start_{s_name}_{step}", lowBound=0, cat='Continuous')

# Completion time variable
C = pulp.LpVariable("Completion_Time", lowBound=0, cat='Continuous')

# Binary sequencing variables: x[(i,j),(k,l)] = 1 if shipment i step j comes before shipment k step l
seq_vars = {}
for i, (s_i, route_i) in enumerate(shipments.items()):
    for j, (hub_i, dur_i) in enumerate(route_i):
        for k, (s_k, route_k) in enumerate(shipments.items()):
            if i == k:
                continue
            for l, (hub_k, dur_k) in enumerate(route_k):
                if hub_i != hub_k:
                    continue
                seq_vars[((s_i, j), (s_k, l))] = pulp.LpVariable(
                    f"seq_{s_i}_{j}_{s_k}_{l}", cat='Binary')

# Objective function
model += C

# Constraints

# 1. Precedence constraints within each shipment's route
for s_name, route in shipments.items():
    for step in range(len(route) - 1):
        hub_idx, dur = route[step]
        next_hub_idx, next_dur = route[step + 1]
        model += start_vars[(s_name, step + 1)] >= start_vars[(s_name, step)] + dur

# 2. Hub capacity constraints (only one shipment at a hub at a time)
M = 1000  # Large enough constant
for i, (s_i, route_i) in enumerate(shipments.items()):
    for j, (hub_i, dur_i) in enumerate(route_i):
        for k, (s_k, route_k) in enumerate(shipments.items()):
            if i == k:
                continue
            for l, (hub_k, dur_k) in enumerate(route_k):
                if hub_i != hub_k:
                    continue
                # At least one must come before the other
                model += seq_vars[((s_i, j), (s_k, l))] + seq_vars[((s_k, l), (s_i, j))] == 1

                # If (i,j) comes before (k,l)
                model += start_vars[(s_i, j)] + dur_i <= start_vars[(s_k, l)] + M * (1 - seq_vars[((s_i, j), (s_k, l))])

                # If (k,l) comes before (i,j)
                model += start_vars[(s_k, l)] + dur_k <= start_vars[(s_i, j)] + M * (1 - seq_vars[((s_k, l), (s_i, j))])

# 3. Completion time definition
for s_name, route in shipments.items():
    last_step = len(route) - 1
    hub_idx, dur = route[last_step]
    model += C >= start_vars[(s_name, last_step)] + dur

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time:", pulp.value(C))

print("\nStart times:")
for var in start_vars.values():
    if pulp.value(var) > 0:
        print(f"{var.name}: {pulp.value(var):.1f}")

print("\nSequencing decisions:")
for var in seq_vars.values():
    if pulp.value(var) == 1:
        print(f"{var.name}: {pulp.value(var)}")

import pulp

# Initialize the problem
model = pulp.LpProblem("Cargo_Shipment_Scheduling", pulp.LpMinimize)

# Data from the problem
shipments = ['S1', 'S2', 'S3']
hubs = ['H1', 'H2', 'H3']

# Routes: (hub, duration) pairs for each shipment
routes = {
    'S1': [('H2', 2), ('H1', 2), ('H3', 6)],
    'S2': [('H2', 7), ('H1', 6), ('H3', 10)],
    'S3': [('H3', 8), ('H1', 9), ('H2', 5)]
}

# Create decision variables
# Start time variables: s[shipment][hub]
s = pulp.LpVariable.dicts("start_time", (shipments, hubs), lowBound=0, cat='Continuous')

# Binary sequencing variables: x[shipment1][shipment2][hub]
# Only create variables for shipments that both visit the hub
x = {}
for hub in hubs:
    visiting_shipments = [s for s in shipments if any(h == hub for h, _ in routes[s])]
    for s1 in visiting_shipments:
        for s2 in visiting_shipments:
            if s1 != s2:
                x[(s1, s2, hub)] = pulp.LpVariable(f"sequence_{s1}_{s2}_{hub}", cat='Binary')

# Completion time variable
C_max = pulp.LpVariable("C_max", lowBound=0, cat='Continuous')

# Objective function
model += C_max

# Constraints for each shipment's route precedence
for shipment in shipments:
    for step in range(len(routes[shipment]) - 1):
        current_hub, current_duration = routes[shipment][step]
        next_hub, next_duration = routes[shipment][step + 1]
        model += s[shipment][next_hub] >= s[shipment][current_hub] + current_duration

