    visiting_shipments = [s for s in shipments if any(h == hub for h, _ in routes[s])]
    if len(visiting_shipments) < 2:
        continue  # No sequencing needed for single shipment

    for i in range(len(visiting_shipments)):
        for j in range(i + 1, len(visiting_shipments)):
            s1 = visiting_shipments[i]
            s2 = visiting_shipments[j]

            # Find duration for this hub for both shipments
            d1 = next(d for h, d in routes[s1] if h == hub)
            d2 = next(d for h, d in routes[s2] if h == hub)

            # Either s1 precedes s2 or s2 precedes s1
            model += s[s1][hub] + d1 <= s[s2][hub] + 1000 * (1 - x[(s1, s2, hub)])
            model += s[s2][hub] + d2 <= s[s1][hub] + 1000 * x[(s1, s2, hub)]

