import pulp

# Problem data
trucks = {
    1: [('C5', 8), ('C2', 8), ('C4', 5), ('C1', 1), ('C3', 4), ('C6', 9)],
    2: [('C6', 2), ('C2', 5), ('C4', 3), ('C3', 10), ('C5', 7), ('C1', 4)],
    3: [('C3', 6), ('C6', 4), ('C4', 6), ('C1', 8), ('C5', 4), ('C2', 5)],
    4: [('C3', 3), ('C2', 6), ('C6', 1), ('C1', 8), ('C5', 1), ('C4', 1)],
    5: [('C2', 1), ('C1', 6), ('C5', 7), ('C4', 3), ('C6', 4), ('C3', 8)],
    6: [('C4', 7), ('C2', 7), ('C3', 1), ('C5', 7), ('C1', 5), ('C6', 9)]
}

# Create mapping from center name to index (0-5)
centers = sorted(list({c for route in trucks.values() for c, _ in route}))
center_to_idx = {c: i for i, c in enumerate(centers)}

# Create problem
model = pulp.LpProblem("Truck_Scheduling", pulp.LpMinimize)

# Decision variables
max_completion = pulp.LpVariable("Makespan", lowBound=0, cat='Continuous')
C = {}  # Completion time of truck i at step j
for i in trucks:
    C[i] = [pulp.LpVariable(f"C_{i}_{j}", lowBound=0, cat='Continuous') for j in range(len(trucks[i]))]

# Binary precedence variables for each center
X = {}
for c in centers:
    center_idx = center_to_idx[c]
    # Find all (truck, step) pairs that visit this center
    steps = []
    for i in trucks:
        for j, (center, _) in enumerate(trucks[i]):
            if center == c:
                steps.append((i, j))
    # Create binary variables for all pairs
    for idx1, (i1, j1) in enumerate(steps):
        for idx2, (i2, j2) in enumerate(steps):
            if idx1 < idx2:  # Avoid duplicate pairs
                X[(i1, j1, i2, j2)] = pulp.LpVariable(f"X_{i1}_{j1}_{i2}_{j2}", cat='Binary')
                X[(i2, j2, i1, j1)] = pulp.LpVariable(f"X_{i2}_{j2}_{i1}_{j1}", cat='Binary')

# Objective function
model += max_completion, "Minimize makespan"

# Constraints
# 1. Makespan must be >= all truck completion times
for i in trucks:
    model += max_completion >= C[i][-1], f"Makespan_{i}"

# 2. Sequence constraints within each truck
for i in trucks:
    for j in range(1, len(trucks[i])):
        prev_center, prev_time = trucks[i][j-1]
        curr_center, curr_time = trucks[i][j]
        model += C[i][j] >= C[i][j-1] + curr_time, f"Seq_{i}_{j}"

# 3. Disjunctive constraints for each center
for c in centers:
    center_idx = center_to_idx[c]
    steps = []
    for i in trucks:
        for j, (center, time) in enumerate(trucks[i]):
            if center == c:
                steps.append((i, j, time))

    for idx1, (i1, j1, t1) in enumerate(steps):
        for idx2, (i2, j2, t2) in enumerate(steps):
            if idx1 < idx2:
                # Either i1's operation comes before i2's
                model += C[i1][j1] + t2 <= C[i2][j2] + 1000 * (1 - X[(i1, j1, i2, j2)]), f"Disj1_{i1}_{j1}_{i2}_{j2}"
                # Or i2's operation comes before i1's
                model += C[i2][j2] + t1 <= C[i1][j1] + 1000 * (1 - X[(i2, j2, i1, j1)]), f"Disj2_{i1}_{j1}_{i2}_{j2}"
                # At least one must be true
                model += X[(i1, j1, i2, j2)] + X[(i2, j2, i1, j1)] >= 1, f"Disj3_{i1}_{j1}_{i2}_{j2}"

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time (makespan):", pulp.value(max_completion))

# Print schedule for each truck
for i in trucks:
    print(f"\nTruck {i} schedule:")
    for j, (center, time) in enumerate(trucks[i]):
        start_time = pulp.value(C[i][j]) - time
        print(f"  {center}: {start_time:.1f} - {pulp.value(C[i][j]):.1f}")

# Print center utilization
print("\nCenter utilization:")
for c in centers:
    print(f"\nCenter {c}:")
    steps = []
    for i in trucks:
        for j, (center, time) in enumerate(trucks[i]):
            if center == c:
                steps.append((i, j, time, pulp.value(C[i][j])))
    # Sort by completion time
    steps.sort(key=lambda x: x[3])
    for i, j, time, completion in steps:
        start = completion - time
        print(f"  Truck {i} step {j+1}: {start:.1f} - {completion:.1f}")

import pulp

# Initialize the problem
model = pulp.LpProblem("Hospital_Test_Scheduling", pulp.LpMinimize)

# Data from the problem
patients = ['A', 'B', 'C']
equipment_sequence = {
    'A': [('X', 2), ('Z', 4), ('Y', 6)],
    'B': [('X', 1), ('Y', 2), ('Z', 3)],
    'C': [('Z', 10), ('X', 9), ('Y', 10)]
}

# Create decision variables
start_times = {}
for p in patients:
    for i in range(len(equipment_sequence[p])):
        start_times[(p, i)] = pulp.LpVariable(f"start_{p}_{i}", lowBound=0, cat='Continuous')

makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for ordering constraints
order_vars = {}
for p1 in patients:
    for i1 in range(len(equipment_sequence[p1])):
        equip1, dur1 = equipment_sequence[p1][i1]
        for p2 in patients:
            for i2 in range(len(equipment_sequence[p2])):
                equip2, dur2 = equipment_sequence[p2][i2]
                if p1 != p2 or i1 != i2:
                    if equip1 == equip2:
                        order_vars[(p1, i1, p2, i2)] = pulp.LpVariable(
                            f"order_{p1}_{i1}_{p2}_{i2}", cat='Binary')

# Objective function
model += makespan

# Constraints

# 1. Precedence constraints within each patient's sequence
for p in patients:
    for i in range(len(equipment_sequence[p]) - 1):
        _, dur = equipment_sequence[p][i]
        model += start_times[(p, i + 1)] >= start_times[(p, i)] + dur

# 2. Equipment capacity constraints (only one test at a time per equipment)
for p1 in patients:
    for i1 in range(len(equipment_sequence[p1])):
        equip1, dur1 = equipment_sequence[p1][i1]
        for p2 in patients:
            for i2 in range(len(equipment_sequence[p2])):
                if (p1, i1, p2, i2) in order_vars:
                    equip2, dur2 = equipment_sequence[p2][i2]
                    # Either p1's test finishes before p2's starts, or vice versa
                    model += start_times[(p1, i1)] + dur1 <= start_times[(p2, i2)] + \
                             (1 - order_vars[(p1, i1, p2, i2)]) * 10000
                    model += start_times[(p2, i2)] + dur2 <= start_times[(p1, i1)] + \
                             order_vars[(p1, i1, p2, i2)] * 10000

# 3. Makespan definition
for p in patients:
    _, dur = equipment_sequence[p][-1]
    model += makespan >= start_times[(p, len(equipment_sequence[p]) - 1)] + dur

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Optimal Schedule:")
for p in patients:
