# Problem data
outlets = ['A', 'B', 'C', 'D']
tech_names = ['Tech1', 'Tech2', 'Tech3', 'Tech4']

# Outlet data: discharge_coeff, flow_rate
outlet_data = {
    'A': {'coeff': 0.986, 'flow': 214.015},
    'B': {'coeff': 2.241, 'flow': 51.386},
    'C': {'coeff': 1.736, 'flow': 237.741},
    'D': {'coeff': 1.11, 'flow': 242.512}
}

# Technology removal efficacies
tech_efficacy = {
    'Tech1': 0.82,
    'Tech2': 0.56,
    'Tech3': 0.76,
    'Tech4': 0.13
}

# Cost matrix: outlet -> technology -> cost per unit flow
cost_matrix = {
    'A': {'Tech1': 108.412, 'Tech2': 19.541, 'Tech3': 57.348, 'Tech4': 171.184},
    'B': {'Tech1': 96.728, 'Tech2': 162.269, 'Tech3': 136.84, 'Tech4': 197.7},
    'C': {'Tech1': 123.136, 'Tech2': 190.508, 'Tech3': 179.371, 'Tech4': 126.404},
    'D': {'Tech1': 146.662, 'Tech2': 105.908, 'Tech3': 167.808, 'Tech4': 114.096}
}

P = 0.649  # Minimum required reduction fraction

# Create the optimization model
model = pulp.LpProblem("TDS_Reduction_Optimization", pulp.LpMinimize)

# Create decision variables: x[outlet][tech] = fraction of outlet's flow treated by tech
x = {}
for outlet in outlets:
    x[outlet] = {}
    for tech in tech_names:
        x[outlet][tech] = pulp.LpVariable(f"x_{outlet}_{tech}", lowBound=0, upBound=1, cat='Continuous')

# Additional variables for untreated fraction of each outlet
y = {}
for outlet in outlets:
    y[outlet] = pulp.LpVariable(f"y_{outlet}", lowBound=0, upBound=1, cat='Continuous')

# Objective: minimize total cost
model += pulp.lpSum(
    cost_matrix[outlet][tech] * outlet_data[outlet]['flow'] * x[outlet][tech]
    for outlet in outlets for tech in tech_names
)

# Baseline TDS discharge (without treatment)
baseline_TDS = sum(
    outlet_data[outlet]['coeff'] * outlet_data[outlet]['flow']
    for outlet in outlets
)

# Reduced TDS discharge after treatment
reduced_TDS = pulp.lpSum(
    outlet_data[outlet]['coeff'] * outlet_data[outlet]['flow'] * (
        y[outlet] + pulp.lpSum((1 - tech_efficacy[tech]) * x[outlet][tech] for tech in tech_names)
    )
    for outlet in outlets
)

# Constraint: sum of treated fractions + untreated fraction = 1 for each outlet
