import pulp

# Data from the problem
fields = ['A', 'B', 'C', 'D']
leaching_coeff = {'A': 1.555, 'B': 1.196, 'C': 1.125, 'D': 2.808}
areas = {'A': 160.783, 'B': 265.337, 'C': 187.581, 'D': 62.647}
practices = [1, 2, 3, 4]
reduction_effectiveness = {1: 0.10, 2: 0.23, 3: 0.12, 4: 0.16}
cost_matrix = {
    'A': {1: 171.252, 2: 41.599, 3: 102.272, 4: 50.612},
    'B': {1: 86.198, 2: 21.141, 3: 82.005, 4: 197.209},
    'C': {1: 60.389, 2: 158.973, 3: 96.452, 4: 90.371},
    'D': {1: 191.89, 2: 199.13, 3: 115.596, 4: 146.498}
}
P = 0.277

# Precompute baseline load
total_baseline = sum(leaching_coeff[field] * areas[field] for field in fields)

# For each field, generate all possible subsets of practices (16 per field)
from itertools import combinations

# Initialize model
model = pulp.LpProblem("Nutrient_Runoff_Mitigation", pulp.LpMinimize)

# Decision variables: y[field][subset_index] = 1 if subset is chosen for field
y = {}
subset_info = {}  # {field: {subset_index: {'reduction': ..., 'cost': ...}}}

for field in fields:
    subset_info[field] = {}
    subset_index = 0
    # Generate all subsets of practices
    for k in range(len(practices) + 1):
        for subset in combinations(practices, k):
            # Calculate combined reduction and cost for this subset
            combined_reduction = 1.0
            total_cost = 0.0
            for j in subset:
                combined_reduction *= (1 - reduction_effectiveness[j])
                total_cost += cost_matrix[field][j] * areas[field]
            combined_reduction = 1 - combined_reduction  # net reduction
            # Only consider non-empty subsets (empty subset is handled separately)
            if k > 0:
                subset_info[field][subset_index] = {
                    'reduction': combined_reduction,
                    'cost': total_cost
                }
                y[(field, subset_index)] = pulp.LpVariable(f"y_{field}_{subset_index}", cat='Binary')
                subset_index += 1
    # Add empty subset (no practices)
    subset_info[field][subset_index] = {
        'reduction': 0.0,
        'cost': 0.0
    }
    y[(field, subset_index)] = pulp.LpVariable(f"y_{field}_{subset_index}", cat='Binary')

# Objective: minimize total cost
model += pulp.lpSum(y[(field, subset_idx)] * subset_info[field][subset_idx]['cost']
                   for field in fields for subset_idx in subset_info[field]), "Total_Cost"

# Constraint: total reduced load <= (1 - P) * total_baseline
reduced_load_expr = pulp.lpSum(
    leaching_coeff[field] * areas[field] * (
        1 - pulp.lpSum(
            y[(field, subset_idx)] * subset_info[field][subset_idx]['reduction']
            for subset_idx in subset_info[field]
        )
    )
    for field in fields
)
model += reduced_load_expr <= (1 - P) * total_baseline, "Total_Reduction_Constraint"

# Each field must choose exactly one subset
for field in fields:
    model += pulp.lpSum(y[(field, subset_idx)] for subset_idx in subset_info[field]) == 1, f"One_Subset_Constraint_{field}"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output the results
print("Status:", pulp.LpStatus[model.status])
print("Total Cost:", pulp.value(model.objective))

for field in fields:
    for subset_idx in subset_info[field]:
        if y[(field, subset_idx)].varValue > 0.5:
            print(f"Field {field}:")
            print(f"  Subset index: {subset_idx}")
            if subset_idx == len(subset_info[field]) - 1:
                print("  No practices applied")
            else:
                reduction = subset_info[field][subset_idx]['reduction']
                cost = subset_info[field][subset_idx]['cost']
                practices_applied = []
                for k in range(len(practices)):
                    for j in combinations(practices, k+1):
                        if j == tuple(sorted(j)):  # Avoid duplicate subsets
                            idx = list(subset_info[field].keys())[list(combinations(practices, k+1)).index(j)]
                            if idx == subset_idx:
                                practices_applied = list(j)
                print(f"  Practices applied: {practices_applied}")
                print(f"  Reduction: {reduction * 100:.2f}%")
                print(f"  Cost: {cost:.2f}")

