    'P5': [('B', 3), ('E', 4), ('D', 7), ('A', 6), ('C', 10)]
}

# Create the model
model = pulp.LpProblem("Job_Shop_Scheduling", pulp.LpMinimize)

# Big M value
M = 1000

# Decision variables
start_time = {}
for j in products:
    for k in range(len(product_sequences[j])):
        start_time[(j, k)] = pulp.LpVariable(f"start_{j}_{k}", lowBound=0, cat='Continuous')

completion_time = {}
for j in products:
    completion_time[j] = pulp.LpVariable(f"completion_{j}", lowBound=0, cat='Continuous')

makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for sequencing
sequence = {}
for j1 in products:
    for k1 in range(len(product_sequences[j1])):
        for j2 in products:
            for k2 in range(len(product_sequences[j2])):
                if j1 != j2 or k1 != k2:
                    sequence[(j1, k1, j2, k2)] = pulp.LpVariable(
                        f"seq_{j1}_{k1}_{j2}_{k2}", cat='Binary')

# Objective function
model += makespan

# Constraints

# 1. Precedence constraints within each product
for j in products:
    for k in range(len(product_sequences[j]) - 1):
        model += start_time[(j, k)] + product_sequences[j][k][1] <= start_time[(j, k+1)]

# 2. Completion time definition
for j in products:
    last_k = len(product_sequences[j]) - 1
    model += start_time[(j, last_k)] + product_sequences[j][last_k][1] == completion_time[j]

# 3. Makespan definition
for j in products:
    model += completion_time[j] <= makespan

# 4. No overlapping operations on the same station
for j1 in products:
    for k1 in range(len(product_sequences[j1])):
        station1 = product_sequences[j1][k1][0]
        dur1 = product_sequences[j1][k1][1]
        for j2 in products:
