                if j1 == j2 and k1 == k2:
                    continue
                station2 = product_sequences[j2][k2][0]
                dur2 = product_sequences[j2][k2][1]
                if station1 == station2:
                    # Either operation 1 comes before operation 2
                    model += start_time[(j1, k1)] + dur1 <= start_time[(j2, k2)] + M * (1 - sequence[(j1, k1, j2, k2)])
                    # Or operation 2 comes before operation 1
                    model += start_time[(j2, k2)] + dur2 <= start_time[(j1, k1)] + M * sequence[(j1, k1, j2, k2)]

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Optimal Makespan:", pulp.value(makespan))

