# Binary variables for precedence at each DC
x = {}
for dc in dcs:
    for i1 in trucks:
        for j1 in range(7):
            if routes[i1][j1][0] == dc:
                for i2 in trucks:
                    if i1 == i2:
                        continue
                    for j2 in range(7):
                        if routes[i2][j2][0] == dc:
                            x[(i1, j1, i2, j2)] = pulp.LpVariable(f"x_{i1}_{j1}_{i2}_{j2}", cat='Binary')

# Objective function
