import pulp

# Data from the problem
patients = {
    1: [('C', 5), ('B', 5), ('A', 7), ('D', 7)],
    2: [('D', 4), ('A', 5), ('C', 6), ('B', 1)],
    3: [('A', 8), ('B', 10), ('C', 2), ('D', 3)],
    4: [('C', 7), ('B', 8), ('A', 1), ('D', 2)]
}

# Reverse mapping: machine -> list of (patient, procedure_index)
machine_procs = {'A': [], 'B': [], 'C': [], 'D': []}
for p in patients:
    for idx, (mach, dur) in enumerate(patients[p]):
        machine_procs[mach].append((p, idx))

# Create the problem
model = pulp.LpProblem("Hospital_Scheduling", pulp.LpMinimize)

# Big-M
M = 1000

# Decision variables: start time of each procedure
start_vars = {}
for p in patients:
    for idx in range(len(patients[p])):
        start_vars[(p, idx)] = pulp.LpVariable(f"s_{p}_{idx}", lowBound=0, cat='Continuous')

# Objective: minimize makespan
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')
model += makespan

# Constraints: makespan >= completion time of every procedure
for p in patients:
    for idx in range(len(patients[p])):
        mach, dur = patients[p][idx]
        model += makespan >= start_vars[(p, idx)] + dur

# Constraints: sequence for each patient
for p in patients:
    for idx in range(len(patients[p]) - 1):
        model += start_vars[(p, idx + 1)] >= start_vars[(p, idx)] + patients[p][idx][1]

# Disjunctive constraints for each machine
binary_vars = {}
for mach in machine_procs:
    procs = machine_procs[mach]
    n = len(procs)
    for i in range(n):
        for j in range(i + 1, n):
            p1, idx1 = procs[i]
            p2, idx2 = procs[j]
            var_name = f"x_{p1}_{idx1}_{p2}_{idx2}"
            binary_vars[(p1, idx1, p2, idx2)] = pulp.LpVariable(var_name, cat='Binary')
            # Constraint 1: s_i >= s_j + dur_j - M*(1 - x)
            model += start_vars[(p1, idx1)] >= start_vars[(p2, idx2)] + patients[p2][idx2][1] - M * (1 - binary_vars[(p1, idx1, p2, idx2)])
            # Constraint 2: s_j >= s_i + dur_i - M*x
            model += start_vars[(p2, idx2)] >= start_vars[(p1, idx1)] + patients[p1][idx1][1] - M * binary_vars[(p1, idx1, p2, idx2)]

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print solution
print("Status:", pulp.LpStatus[model.status])
print("Minimized Makespan:", pulp.value(makespan))
print("\nStart Times:")
