        for j, (t2, seq2, dur2) in enumerate(dock_ops):
            if i < j:
                var_name = f"seq_d{d}_t{t1}_seq{seq1}_t{t2}_seq{seq2}"
                seq_vars[(d, t1, seq1, t2, seq2)] = pulp.LpVariable(var_name, cat='Binary')
                seq_vars[(d, t2, seq2, t1, seq1)] = pulp.LpVariable(var_name + "_rev", cat='Binary')

# Objective: minimize the maximum completion time
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')
model += makespan

# Constraints
# 1. Completion time for each truck is the end of its last operation
for t in trucks:
    last_seq = len(truck_sequences[t]) - 1
    last_dock = truck_sequences[t][last_seq][0]
    dur = truck_sequences[t][last_seq][1]
    model += completion_times[t] == start_times[(t, last_dock, last_seq)] + dur
    model += makespan >= completion_times[t]

# 2. Sequence constraints within each truck
for t in trucks:
    for seq_idx in range(len(truck_sequences[t]) - 1):
        current_dock, current_dur = truck_sequences[t][seq_idx]
        next_dock, next_dur = truck_sequences[t][seq_idx + 1]
        model += start_times[(t, next_dock, seq_idx + 1)] >= start_times[(t, current_dock, seq_idx)] + current_dur

# 3. Dock capacity constraints (no overlap)
for d in docks:
    # Find all truck operations at this dock
    dock_ops = []
    for t in trucks:
        for seq_idx, (dock, dur) in enumerate(truck_sequences[t]):
            if dock == d:
                dock_ops.append((t, seq_idx, dur))

    # For each pair of operations at this dock, add no-overlap constraints
    for i, (t1, seq1, dur1) in enumerate(dock_ops):
        for j, (t2, seq2, dur2) in enumerate(dock_ops):
            if i < j:
                # Either t1 comes before t2 or vice versa
                model += start_times[(t1, d, seq1)] + dur1 <= start_times[(t2, d, seq2)] + 1000 * (1 - seq_vars[(d, t1, seq1, t2, seq2)])
                model += start_times[(t2, d, seq2)] + dur2 <= start_times[(t1, d, seq1)] + 1000 * seq_vars[(d, t1, seq1, t2, seq2)]

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print("Status:", pulp.LpStatus[model.status])
print("Total completion time (makespan):", pulp.value(makespan))

print("\nStart times for each operation:")
