                model += C[(i1, j1)] >= C[(i2, j2)] + duration[(i1, j1)] - 1000 * (1 - x[(i1, j1, i2, j2)])
                model += C[(i2, j2)] >= C[(i1, j1)] + duration[(i2, j2)] - 1000 * x[(i1, j1, i2, j2)]

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

