# Create hub to tasks mapping
hub_to_tasks = {}
for r in routes:
    for idx, (hub, dur) in enumerate(routes[r]):
        if hub not in hub_to_tasks:
            hub_to_tasks[hub] = []
        hub_to_tasks[hub].append((r, idx))

