# 1. Precedence constraints within each route
for r in routes:
    for idx in range(len(routes[r])-1):
        current_dur = routes[r][idx][1]
        next_start = start_vars[(r, idx+1)]
        model += next_start >= start_vars[(r, idx)] + current_dur, f"Precedence_{r}_{idx}"

