for hub in hub_to_tasks:
    tasks = hub_to_tasks[hub]
    for i in range(len(tasks)):
        for j in range(i+1, len(tasks)):
            r1, idx1 = tasks[i]
            r2, idx2 = tasks[j]
            dur1 = routes[r1][idx1][1]
            dur2 = routes[r2][idx2][1]

            # Either task1 comes before task2 or vice versa
            model += start_vars[(r1, idx1)] + dur1 <= start_vars[(r2, idx2)] + (1 - sequence_vars[(r1, idx1, r2, idx2)]) * 10000, f"NoOverlap1_{r1}_{idx1}_{r2}_{idx2}"
