                    order[h][r1][i1] = {}
                    order[h][r1][i1][r2] = {}
                    order[h][r1][i1][r2][i2] = pulp.LpVariable(f"order_{h}_{r1}_{i1}_{r2}_{i2}", cat='Binary')

