# Hub capacity constraints
for h in range(num_hubs):
    for r1 in range(num_routes):
        for i1 in range(len(routes[r1])):
            if routes[r1][i1][0] != h:
                continue
            for r2 in range(num_routes):
                for i2 in range(len(routes[r2])):
                    if routes[r2][i2][0] != h:
                        continue
                    if r1 == r2 and i1 == i2:
                        continue
                    # Binary order variable constraints
                    M = 1000  # Big M
                    model += end[r1][i1] <= start[r2][i2] + M * (1 - order[h][r1][i1][r2][i2])
                    model += end[r2][i2] <= start[r1][i1] + M * order[h][r1][i1][r2][i2]

# Makespan constraints
for r in range(num_routes):
    model += makespan >= end[r][-1]

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Optimal makespan: {makespan.varValue:.2f}")

# Print detailed schedule
for r in range(num_routes):
    print(f"\nRoute {r+1}:")
    for i in range(len(routes[r])):
        hub = routes[r][i][0]
        start_time = start[r][i].varValue
        end_time = end[r][i].varValue
        print(f"  Hub H{hub+1}: starts at {start_time:.2f}, ends at {end_time:.2f}")

