import pulp

# Define the facilities and travel times
facilities = ['P', 'Q', 'R', 'S', 'T', 'U']
travel_times = {
    ('P', 'Q'): 37.1, ('P', 'R'): 49.0, ('P', 'S'): 77.3, ('P', 'T'): 66.9, ('P', 'U'): 61.0,
    ('Q', 'P'): 37.1, ('Q', 'R'): 24.1, ('Q', 'S'): 89.1, ('Q', 'T'): 40.0, ('Q', 'U'): 27.7,
    ('R', 'P'): 49.0, ('R', 'Q'): 24.1, ('R', 'S'): 74.0, ('R', 'T'): 59.7, ('R', 'U'): 16.3,
    ('S', 'P'): 77.3, ('S', 'Q'): 89.1, ('S', 'R'): 74.0, ('S', 'T'): 129.2, ('S', 'U'): 89.0,
    ('T', 'P'): 66.9, ('T', 'Q'): 40.0, ('T', 'R'): 59.7, ('T', 'S'): 129.2, ('T', 'U'): 52.4,
    ('U', 'P'): 61.0, ('U', 'Q'): 27.7, ('U', 'R'): 16.3, ('U', 'S'): 89.0, ('U', 'T'): 52.4,
}

# Initialize the problem
model = pulp.LpProblem("Traveling_Technician_Problem", pulp.LpMinimize)

# Create binary decision variables for each pair of facilities
x = pulp.LpVariable.dicts("x", (facilities, facilities), cat='Binary')

# Add objective function: minimize total travel time
model += pulp.lpSum(travel_times[(i, j)] * x[i][j] for i in facilities for j in facilities if i != j)

# Add constraints: each facility must be entered and exited exactly once
for j in facilities:
    model += pulp.lpSum(x[i][j] for i in facilities if i != j) == 1
for i in facilities:
    model += pulp.lpSum(x[i][j] for j in facilities if i != j) == 1

# Subtour elimination: Miller-Tucker-Zemlin formulation
n = len(facilities)
u = pulp.LpVariable.dicts("u", facilities, lowBound=0, upBound=n-1, cat='Integer')
start = 'P'  # Arbitrarily choose 'P' as the starting point
for i in facilities:
    if i != start:
        model += u[i] >= 1
        model += u[i] <= n - 1
for i in facilities:
    for j in facilities:
        if i != j and j != start:
            model += u[i] - u[j] + n * x[i][j] <= n - 1

# Solve the problem
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Extract the solution
solution = []
if pulp.LpStatus[model.status] == 'Optimal':
    # Find the starting arc
    for i in facilities:
        for j in facilities:
            if i != j and pulp.value(x[i][j]) == 1:
                solution.append((i, j))
    # Reconstruct the full tour
    tour = [solution[0][0]]
    while len(tour) < n:
        for arc in solution:
            if arc[0] == tour[-1]:
                tour.append(arc[1])
                break
    tour.append(tour[0])  # Return to start
    print("Optimal Tour:", " -> ".join(tour))
    print("Total Travel Time:", pulp.value(model.objective))
else:
    print("No optimal solution found.")
